create or replace function public.validate_time_allocations(p_task uuid) returns void language plpgsql security definer set search_path=public as $$ declare total numeric; allocated numeric; profiles_count int; begin select actual_hours into total from tasks where id=p_task; select coalesce(sum(hours),0) into allocated from task_time_allocations where task_id=p_task; select count(*) into profiles_count from task_profiles where task_id=p_task; if total is not null and allocated<>total then raise exception 'Urenverdeling (%) moet gelijk zijn aan taakuren (%)',allocated,total; end if; if profiles_count=1 and total is not null and allocated=0 then insert into task_time_allocations(task_id,profile_id,hours) select p_task,profile_id,total from task_profiles where task_id=p_task; end if; end $$;
create or replace function public.guard_item_completion() returns trigger language plpgsql as $$ begin if new.status in ('Afgerond','Gearchiveerd') and exists(select 1 from tasks where marketing_item_id=new.id and required and deleted_at is null and status not in ('Afgerond','Gepubliceerd')) then raise exception 'Alle verplichte taken moeten gereed zijn'; end if; return new; end $$;
create trigger item_completion_guard before update of status on marketing_items for each row execute function guard_item_completion();
create or replace function public.audit_task_changes() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into activity_log(actor_id,entity_type,entity_id,event,new_values) values(auth.uid(),'task',new.id,'task.created',to_jsonb(new)); else if old.assignee_id is distinct from new.assignee_id then insert into activity_log(actor_id,entity_type,entity_id,event,old_values,new_values) values(auth.uid(),'task',new.id,'task.assignee_changed',jsonb_build_object('assignee_id',old.assignee_id),jsonb_build_object('assignee_id',new.assignee_id)); end if; if old.status is distinct from new.status then insert into activity_log(actor_id,entity_type,entity_id,event,old_values,new_values) values(auth.uid(),'task',new.id,'task.status_changed',jsonb_build_object('status',old.status),jsonb_build_object('status',new.status)); end if; if old.deadline is distinct from new.deadline or old.planned_date is distinct from new.planned_date then insert into activity_log(actor_id,entity_type,entity_id,event,old_values,new_values) values(auth.uid(),'task',new.id,'task.planning_changed',jsonb_build_object('deadline',old.deadline,'planned_date',old.planned_date),jsonb_build_object('deadline',new.deadline,'planned_date',new.planned_date)); end if; end if; return new; end $$;
create trigger task_audit after insert or update on tasks for each row execute function audit_task_changes();
